lifecycle.secure:
import path from 'node:path';
app.get('/files/:name', (req, res) => {
  const base = '/srv/data';
  const target = path.resolve(base, req.params.name);
  if (!target.startsWith(base + path.sep)) return res.sendStatus(400);
  res.sendFile(target);
});

